'use strict';

// MODULES //

var isArrayBuffer = require( '@stdlib/assert/is-arraybuffer' );
var factory = require( '@stdlib/ndarray/matrix/ctor' ).factory;
var format = require( '@stdlib/string/format' );


// VARIABLES //

var ctor = factory( 'generic' );


// MAIN //

/**
* Returns a "generic" matrix (i.e., a two-dimensional ndarray).
*
* @param {(NonNegativeInteger|NonNegativeIntegerArray|ArrayLikeObject<Collection>|Iterable)} [arg0] - shape, number of rows, array-like object, or iterable
* @param {NonNegativeInteger} [arg1] - number of columns
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only matrix
* @param {string} [options.mode='throw'] - specifies how to handle indices which exceed matrix dimensions
* @param {StringArray} [options.submode=[options.mode]] - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @throws {TypeError} first argument must be either a shape, integer, array-like object, iterable, or options object
* @throws {TypeError} must provide valid options
* @returns {ndarray} two-dimensional ndarray
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var v = new GenericMatrix();
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 0, 0 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var v = new GenericMatrix( [ 2, 2 ] );
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var v = new GenericMatrix( 2, 2 );
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var v = new GenericMatrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 2, 2 ]
*/
function GenericMatrix() {
	var arg;
	if ( arguments.length === 0 ) {
		return new ctor();
	}
	arg = arguments[ 0 ];
	if ( isArrayBuffer( arg ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be either a shape, an integer, an array-like object, or an iterable. Value: `%s`.', arg ) );
	}
	if ( arguments.length === 1 ) {
		return new ctor( arg );
	}
	if ( arguments.length === 2 ) {
		return new ctor( arg, arguments[ 1 ] );
	}
	return new ctor( arg, arguments[ 1 ], arguments[ 2 ] );
}


// EXPORTS //

module.exports = GenericMatrix;
